 qs:[
  {auto:{t:"num",v:180}, q:"2023年の外国人の観光客は、何千人ですか。", ans:"180千人（720×0.25）", rubric:[["180",2]], exp:"720×0.25＝180。"},
  {auto:{t:"num",v:3}, q:"2023年の外国人の観光客は、2019年の何倍ですか。", ans:"3倍（2019年は60千人、180÷60）", rubric:[["3（倍）",2]], exp:"2019年の外国人は600×0.1＝60。180÷60＝3。"},
  {q:"外国人の観光客がふえたことで、E町に必要になると考えられる取り組みを、理由とともに書きましょう。", ans:"外国人がふえたので、案内板や地図に、英語など外国語の表示をふやす。言葉が通じないと、道に迷ったり、お店を利用しにくかったりするから。", rubric:[["外国人観光客の増加に合った取り組み（多言語表示・案内・キャッシュレスなど別解可）",2],["その取り組みが必要な理由",2]], exp:"資料の「外国人がふえた」という事実から、そのお客さんが困ることを考える。"}
 ]
